"""General utility functions. These functions are called from the top level IntegrityService
interface. They are not intended to be called directly from a test script"""

import interops.libraries.integrity.integrity_objects as IntegrityObjects
from interops.libraries.integrity.interactions import IntegrityCore
import interops.libraries.integrity.pages.common_menu_bars as CommonMenuPgObj
from interops.libraries.integrity.pages.login_screen import LoginScreen
from typing import Optional as opt
from interops.libraries.icom.icom_th import iCOM_cat as IcomTest
import interops.libraries.integrity.beam_states_constants as BeamStates
import squishtest3 as sq
from remotesystem import RemoteSystem
import logging


logger = logging.getLogger(__name__)

def _utility_close_all_open_applets(close_buttons: opt[list]=None, retries: int=500, log_off: bool=False) -> bool:
    '''
    Iterates through a list of close/cancel buttons until they're all gone.
    Can be sent a custom list

    Args:
        close_buttons (list): Optional list of close/ cancel buttons formatted as squish object mappings
        retries (int): Optional, Number of attempts at pressing the close/ cancel buttons
        log_off (bool): Optional, Log off Integrity after closing all open applets

    Returns:
        bool - True if all open applets have been closed
    '''

    if not close_buttons:
        close_buttons = ["{text='Unconfirm' type='Button'}",
                            "{text='Next Beam' type='Button'}",
                            "{text='X' type='Button'}",
                            "{class='ThunderRT6CommandButton'  id='1' text='' type='Button'}",
                            {"text": 'OK', "type": 'Button', "enabled": "true"},
                            "{text='>' type='Button'}",
                            "{ text='Yes' type='Button'}",
                            IntegrityObjects.rEP_ExitButton,
                            {"container": IntegrityObjects.rEP_FRMDeliveryMonitorCmd, "width": 305}
                            ]
    try:
        for n in range(retries):
            close_button_visible = False
            for close_button in close_buttons:
                if sq.object.exists(close_button):
                    close_button_visible = True
                    try:
                        sq.mouseClick(sq.waitForObject(close_button, 100))
                        break
                    except Exception as e:
                        pass
            if not close_button_visible:
                return True

        logger.info("failed to close all applets")
        return False

    except Exception as e:
        logger.exception("failed to find close button", str(e))
        return False
    finally:
        if log_off:
            IntegrityCore.click_log_off_button()
            IntegrityCore.click_yes_button_on_log_off_dialog()


def _utility_monitor_for_termination(timeout: int=3600, callback=None) -> bool:
    '''
    Monitors the linac status indicator for when a beam is no longer running

    Args:
        timeout (int): is optional (and is defined in seconds), default = 3600s
        callback: is an optional callable object.

    Returns:
        bool - True if beam is no longer running
    '''

    try:
        status = CommonMenuPgObj.StatusIndicator()
        if status.ready():
            beam_running = True
            ok_list = ["Radiation On", "Move Only", "Intersegment", "Terminated Checking"]

            sq.snooze(5)
            while beam_running and timeout > 0:
                if callback:
                    try:
                        callback()
                    except Exception as e:
                        logger.exception("Error executing callback: " + str(e))
                machine_state = status.get_machine_state()
                if any(machine_state in i for i in ok_list):
                    timeout -= 1
                    sq.snooze(1)
                    beam_running = True
                else:
                    beam_running = False
                    logger.info("Exiting monitor_for_termination, machine state: " + machine_state)
                    return True

            logger.info("The machine was stuck in the following machine state: " + machine_state) # type:ignore
        return False
    except Exception as e:
        logger.exception("Problem checking machine state " + str(e))
        return False


def _utility_handle_terminal_inhibits(icom: opt[IcomTest]=None, restart_system: bool=False) -> None:
    '''
    Terminates test if 'terminal' inhibit is present (see terminal_inhibits list)

    Args:
        icom (iCOM_cat): Optional, iCOM_cat object used to obtain the list of inhibits
        restart_system (bool): Optional, Close all open applets, log off and restart Integrity
    '''

    status = CommonMenuPgObj.StatusIndicator()
    top_level_inhibit = status.get_inhibits()
    terminal_inhibits = [
        "LCS Link",
        "MLC Display Server Failure",
        "MLC Link",
        "Fac1",
        "D.Rot. stp",
        "Leaf move error"]
    inhibit_list = [top_level_inhibit]

    if icom:
        '''replace screen read inhibit with icom read inhibits list if available '''
        try:
            inhibit_list = icom.get_inhibits_list()
        except Exception:
            inhibit_list = [top_level_inhibit]

    if (any(x in inhibit_list for x in terminal_inhibits)) or top_level_inhibit in terminal_inhibits:
        sq.test.fatal( #type:ignore
            "Terminal inhibit",
            "Machine is in " +
            status.get_machine_state() +
            " with Inhibit " +
            " , ".join(inhibit_list))
        if restart_system:
            logger.info("restarting system") # type:ignore
            _utility_close_all_open_applets(log_off=True)
            '''write current testcase name to control file for restart'''
            remotesys = RemoteSystem()
            tasklist = ["cmd",
                        "/c",
                        "echo",
                        sq.squishinfo.testCase.split("\\")[-1],
                        ">",
                        "d:\\squish\\test_restarted.txt"]
            remotesys.execute(tasklist)

            try:
                loginscreen = LoginScreen()
                loginscreen.shutdown()
                sq.snooze(60)
            except Exception:
                pass

            tasklist = ["cmd", "/c", "start", "", "d:\\squish\\shell_scripts\\reboot.bat"]
            remotesys.execute(tasklist)

        raise RuntimeError("Test aborted")


def _utility_wait_for_machine_state_list(timeout: int) -> bool:
    '''
    Waits for the machine to be in any of the beam started states

    Args:
        timeout (int): Time to wait (in seconds) for machine to be
        in any of the beam started states

    Returns:
        bool - True if machine is any of the beam started states
    '''
    beam_started_state = False
    try:
        while(timeout > 0):
            status_indicator = CommonMenuPgObj.StatusIndicator()
            if status_indicator.get_machine_state() in BeamStates.BEAM_STARTED_STATES:
                beam_started_state = True
                break
            logger.info("Time", str(timeout))
            sq.snooze(1)
            timeout -= 1
        return beam_started_state
    except Exception as e:
        logger.exception("Wait for machine state error", str(e))
        return beam_started_state